metadata.vithanco:vgl:
vgraph ibisMetaMap: IBIS "Generic IBIS Diagram" {
    node q1: Question "1. What should we do about ... ?";
    node a11: Answer "Idea 1.1";
    node a12: Answer "Idea 1.2";
    node q2: Question "2. How should we do it?";
    node a21: Answer "Idea 2.1";
    node a22: Answer "Idea 2.2";
    node q4: Question "4. What does 'X' mean?";
    node pro21: Pro "";
    node con21: Con "";
    node pro11: Pro "Good idea because ...";
    node con11: Con "A problem here is ...";
    node q3: Question "3. Criteria?";
    node fast: Answer "Fast";
    node cheap: Answer "Cheap";
    node good: Answer "Good";
    node q5: Question "5. What is the cost of this?";
    node a41: Answer "A definition of X";
    node a51: Answer "An estimate of the cost";
    node q6: Question "6. What is the background?";
    node bg: Answer "Background (can easily be a full tree on it's own).";
    node q7: Question "7. Who are the stakeholders?";
    node jones: Answer "Jones";
    node smith: Answer "Smith";
    node black: Answer "Black";

    edge q1 -> a11;
    edge a11 -> q2;
    edge q2 -> a21;
    edge q2 -> a22;
    edge a21 -> q4;
    edge q4 -> a41;
    edge a21 -> pro21;
    edge a21 -> con21;
    edge a11 -> pro11;
    edge a11 -> con11;
    edge q1 -> q3;
    edge q3 -> fast;
    edge q3 -> cheap;
    edge q3 -> good;
    edge q1 -> a12;
    edge a12 -> q5;
    edge q5 -> a51;
    edge q1 -> q6;
    edge q6 -> bg;
    edge q1 -> q7;
    edge q7 -> jones;
    edge q7 -> smith;
    edge q7 -> black;
}
